    if ($FileFormat == UNKNOWN_FORMAT)
      report_writeErrorMsg(ERR_CLIMATE_FILE_READ, $Fclimate.name_)
      return
    end
    c_rewind($Fclimate.file)
    sstrncpy($FileLine, L0, (0 & 0xFFFFFFFFFFFFFFFF))
    if ($Temp.fileStartDate == -693594.0)
      datetime_decodeDate($StartDate.v, $FileYear, $FileMonth, $FileDay)
    else
      datetime_decodeDate($Temp.fileStartDate, $FileYear, $FileMonth, $FileDay)
    end
    while !(c_feof($Fclimate.file) != 0)
      sstrncpy($FileLine, L0, (0 & 0xFFFFFFFFFFFFFFFF))
