  def setNextEvapDate(theDate)
    yr = BX_setNextEvapDate_yr
    yr.v = 0
    mon = BX_setNextEvapDate_mon
    mon.v = 0
    day = BX_setNextEvapDate_day
    day.v = 0
    k = 0
    d = BX_setNextEvapDate_d
    d.v = 0.0
    e = BX_setNextEvapDate_e
    e.v = 0.0
    if ($NextEvapDate.v > theDate)
      return
    end
    case $Evap.type
    when 0
      $NextEvapDate.v = (theDate + 365.0)
    when 1
      datetime_decodeDate(theDate, yr, mon, day)
      if (mon.v == 12)
        mon.v = 1
        yr.v += 1
      else
        mon.v += 1
      end
      $NextEvapDate.v = datetime_encodeDate(yr.v, mon.v, 1)
    when 2
      k = $Evap.tSeries
      if (k >= 0)
        $NextEvapDate.v = (theDate + 365.0)
        while ((table_getNextEntry($Tseries[k], d, e) != 0) && (d.v <= $EndDateTime))
          if (d.v >= theDate)
            $NextEvapDate.v = d.v
            $NextEvapRate.v = e.v
            break
          end
        end
      end
    when 4
      $NextEvapDate.v = (c_floor(theDate) + 1.0)
    else
      $NextEvapDate.v = (theDate + 365.0)
    end
  end

