  def updateFileValues(theDate)
    i = 0
    deltaDays = 0
    deltaDays = d2i(((c_floor(theDate) - c_floor($StartDateTime))))
    if (deltaDays > $FileElapsedDays)
      $FileElapsedDays += 1
      $FileDay.v += 1
      if ($FileDay.v > $FileLastDay)
        $FileMonth.v += 1
        if ($FileMonth.v > 12)
          $FileMonth.v = 1
          $FileYear.v += 1
        end
        readFileValues()
        $FileDay.v = 1
        $FileLastDay = datetime_daysPerMonth($FileYear.v, $FileMonth.v)
      end
      i = TMIN
      while (i <= WIND)
        if ($FileData[i][$FileDay.v] == -10000000000.0)
          i += 1
          next
        end
        $FileValue[i] = $FileData[i][$FileDay.v]
        i += 1
      end
    end
  end

