  # controls.c:439
  def controls_addRuleClause(r, keyword, tok, nToks)
    case keyword
    when 0
      if ($Rules[r].ID == (nil))
        $Rules[r].ID = project_findID(CONTROL, tok[1])
      end
      $InputState = K_r_RULE
      if (nToks > 2)
        return ERR_RULE
      end
      return 0
    when 1
      if ($InputState != K_r_RULE)
        return ERR_RULE
      end
      $InputState = K_r_IF
      return addPremise(r, K_r_AND, tok, nToks)
    when 2
      if ($InputState == K_r_IF)
        return addPremise(r, K_r_AND, tok, nToks)
      elsif (($InputState == K_r_THEN) || ($InputState == K_r_ELSE))
        return addAction(r, tok, nToks)
      else
        return ERR_RULE
      end
    when 3
      if ($InputState != K_r_IF)
        return ERR_RULE
      end
      return addPremise(r, K_r_OR, tok, nToks)
    when 4
      if ($InputState != K_r_IF)
        return ERR_RULE
      end
      $InputState = K_r_THEN
      return addAction(r, tok, nToks)
    when 5
      if ($InputState != K_r_THEN)
        return ERR_RULE
      end
      $InputState = K_r_ELSE
      return addAction(r, tok, nToks)
    when 6
      if (($InputState != K_r_THEN) && ($InputState != K_r_ELSE))
        return ERR_RULE
      end
      $InputState = K_r_PRIORITY
      if !(getDouble(tok[1], fieldref($Rules[r], :priority)) != 0)
        return ERR_NUMBER
      end
      if (nToks > 2)
        return ERR_RULE
      end
      return 0
    end
    return 0
  end

  # controls.c:495
  def controls_evaluate(currentTime, elapsedTime, tStep)
    r = 0
    result = 0
    p = nil
    a = nil
    $CurrentDate = c_floor(currentTime)
    $CurrentTime = (currentTime - c_floor(currentTime))
    $ElapsedTime = elapsedTime
    if ($RuleCount == 0)
      return 0
    end
    clearActionList()
    r = 0
    while (r < $RuleCount)
      result = 1
      p = $Rules[r].firstPremise
      while !p.nil?
        if (p.type == K_r_OR)
          if (result == 0)
            result = evaluatePremise(p, tStep)
          end
        else
          if (result == 0)
            break
          end
          result = evaluatePremise(p, tStep)
        end
        p = p.next_
      end
      if (result == 1)
        a = $Rules[r].thenActions
      else
        a = $Rules[r].elseActions
      end
      while !a.nil?
        updateActionValue(a, currentTime, tStep)
        updateActionList(a)
        a = a.next_
      end
      r += 1
    end
    if !$ActionList.nil?
      return executeActionList(currentTime)
    else
      return 0
    end
  end

  # controls.c:556
  def addPremise(r, type, tok, nToks)
    relation = 0
    n = BX_addPremise_n
    n.v = 0
    err = 0
    value = BX_addPremise_value
    value.v = -10000000000.0
    p = nil
    v1 = TVariable.new
    v2 = TVariable.new
    obj = 0
    exprIndex = 0
    varIndex = -1
    if (nToks < 4)
      return ERR_ITEMS
    end
    v1.attribute = -1
    v1.object = -1
    v1.index = -1
    n.v = 1
    exprIndex = getExpressionIndex(tok[1])
    if (exprIndex < 0)
      varIndex = getVariableIndex(tok[n.v])
      if (varIndex >= 0)
        v1 = $NamedVariable[varIndex].variable.copy
      else
        err = getPremiseVariable(tok, nToks, n, v1)
        if (err > 0)
          return err
        end
      end
    end
    n.v += 1
    if (n.v >= nToks)
      return error_setInpError(ERR_ITEMS, L0)
    end
    relation = findExactMatch(tok[n.v], $RelOpWords)
    if (relation < 0)
      return error_setInpError(ERR_KEYWORD, tok[n.v])
    end
    v2.attribute = -1
    v2.object = -1
    v2.index = -1
    n.v += 1
    if (n.v >= nToks)
      return error_setInpError(ERR_ITEMS, L0)
    end
    varIndex = getVariableIndex(tok[n.v])
    if (varIndex >= 0)
      v2 = $NamedVariable[varIndex].variable.copy
    else
      obj = findmatch(tok[n.v], $ObjectWords)
      if (obj >= 0)
        err = getPremiseVariable(tok, nToks, n, v2)
        if (err > 0)
          return ERR_RULE
        end
        if ((exprIndex < 0) && (v1.attribute != v2.attribute))
          report_writeWarningMsg(L34, $Rules[r].ID)
        end
      else
        err = getPremiseValue(tok[n.v], v1.attribute, value)
        if (err > 0)
          return err
        end
      end
    end
    n.v += 1
    if ((n.v < nToks) && (findmatch(tok[n.v], $RuleKeyWords) >= 0))
      return ERR_RULE
    end
    p = TPremise.new
    if !(!p.nil?)
      return ERR_MEMORY
    end
    p.type = type
    p.exprIndex = exprIndex
    p.lhsVar = v1.copy
    p.rhsVar = v2.copy
    p.relation = relation
    p.value = value.v
    p.next_ = (nil)
    if $Rules[r].firstPremise.equal?((nil))
      $Rules[r].firstPremise = p
    else
      $Rules[r].lastPremise.next_ = p
    end
    $Rules[r].lastPremise = p
    return 0
  end

  # controls.c:668
  def getPremiseVariable(tok, nToks, k, v)
    n = k.v
    object = -1
    index = -1
    obj = 0
    attrib = 0
    obj = findmatch(tok[n], $ObjectWords)
    if (obj < 0)
      return error_setInpError(ERR_KEYWORD, tok[n])
    end
    n += 1
    if (n >= nToks)
      return error_setInpError(ERR_ITEMS, L0)
    end
    case obj
    when 0
      index = project_findObject(GAGE, tok[n])
      if (index < 0)
        return error_setInpError(ERR_NAME, tok[n])
      end
      object = K_r_GAGE
    when 1
      index = project_findObject(NODE, tok[n])
      if (index < 0)
        return error_setInpError(ERR_NAME, tok[n])
      end
      object = K_r_NODE
    when 2, 3, 4, 5, 6, 7
      index = project_findObject(LINK, tok[n])
      if (index < 0)
        return error_setInpError(ERR_NAME, tok[n])
      end
      object = K_r_LINK
    else
      n -= 1
    end
    n += 1
    if (n >= nToks)
      return error_setInpError(ERR_ITEMS, L0)
    end
    if (object == K_r_GAGE)
      attrib = getGageAttrib(tok[n])
    else
      attrib = findmatch(tok[n], $AttribWords)
    end
    if (attrib < 0)
      return error_setInpError(ERR_KEYWORD, tok[n])
    end
    if (obj == K_r_GAGE)
    elsif (obj == K_r_NODE)
      case attrib
      when 0, 1, 2, 3, 4
      else
        return error_setInpError(ERR_KEYWORD, tok[n])
      end
    elsif (((object == K_r_LINK) && (index >= 0)) && ((((attrib == K_r_TIMEOPEN) || (attrib == K_r_TIMECLOSED)))))
    elsif ((obj == K_r_LINK) || (obj == K_r_CONDUIT))
      case attrib
      when 8, 0, 6, 7, 5, 10, 11, 12
      else
        return error_setInpError(ERR_KEYWORD, tok[n])
      end
    elsif (obj == K_r_PUMP)
      case attrib
      when 5, 9, 8
      else
        return error_setInpError(ERR_KEYWORD, tok[n])
      end
    elsif (((obj == K_r_ORIFICE) || (obj == K_r_WEIR)) || (obj == K_r_OUTLET))
      case attrib
      when 5, 9
      else
        return error_setInpError(ERR_KEYWORD, tok[n])
      end
    else
      case attrib
      when 15, 16, 17, 19, 20, 18
      else
        return error_setInpError(ERR_KEYWORD, tok[n])
      end
    end
    v.object = object
    v.index = index
    v.attribute = attrib
    k.v = n
    return 0
  end

  # controls.c:797
  def getGageAttrib(token)
    attrib = 0
    if (match(token, $IntensityWord) != 0)
      return 0
    end
    attrib = c_atoi(token)
    if ((attrib < 1) || (attrib > 48))
      return -1
