  # controls.c:824
  def getPremiseValue(token, attrib, value)
    strDate = CPtr.buf(25)
    case attrib
    when 8
      value.v = (findmatch(token, $StatusWords)).to_f
      if (value.v < 0.0)
        value.v = (findmatch(token, $ConduitWords)).to_f
      end
      if (value.v < 0.0)
        return error_setInpError(ERR_KEYWORD, token)
      end
    when 15, 17, 13, 14
      if !(datetime_strToTime(token, value) != 0)
        return error_setInpError(ERR_DATETIME, token)
      end
    when 16
      if !(datetime_strToDate(token, value) != 0)
        return error_setInpError(ERR_DATETIME, token)
      end
    when 19
      if !(getDouble(token, value) != 0)
        return error_setInpError(ERR_NUMBER, token)
      end
      if ((value.v < 1.0) || (value.v > 7.0))
        return error_setInpError(ERR_DATETIME, token)
      end
    when 20
      if !(getDouble(token, value) != 0)
        return error_setInpError(ERR_NUMBER, token)
      end
      if ((value.v < 1.0) || (value.v > 12.0))
        return error_setInpError(ERR_DATETIME, token)
      end
    when 18
      sstrncpy(strDate, token, (6 & 0xFFFFFFFFFFFFFFFF))
      sstrcat(strDate, L35, (25 & 0xFFFFFFFFFFFFFFFF))
      if (datetime_strToDate(strDate, value) != 0)
        value.v = (datetime_dayOfYear(value.v)).to_f
      elsif (((!(getDouble(token, value) != 0)) || (value.v < 1.0)) || (value.v > 365.0))
        return error_setInpError(ERR_DATETIME, token)
      end
    else
      if !(getDouble(token, value) != 0)
        return error_setInpError(ERR_NUMBER, token)
      end
    end
    return 0
  end

