    attrib.v = 0
    curve = BX_addAction_curve
    curve.v = -1
    tseries = BX_addAction_tseries
    tseries.v = -1
    n = 0
    err = 0
    values = [1.0, 0.0, 0.0]
    a = nil
    if (nToks < 6)
      return error_setInpError(ERR_ITEMS, L0)
    end
    obj = findmatch(tok[1], $ObjectWords)
    if ((((((obj != K_r_LINK) && (obj != K_r_CONDUIT)) && (obj != K_r_PUMP)) && (obj != K_r_ORIFICE)) && (obj != K_r_WEIR)) && (obj != K_r_OUTLET))
      return error_setInpError(ERR_KEYWORD, tok[1])
    end
    link = project_findObject(LINK, tok[2])
    if (link < 0)
      return error_setInpError(ERR_NAME, tok[2])
    end
    case obj
    when 3
      if ($Link[link].type != CONDUIT)
        return error_setInpError(ERR_NAME, tok[2])
      end
    when 4
      if ($Link[link].type != PUMP)
        return error_setInpError(ERR_NAME, tok[2])
      end
    when 5
      if ($Link[link].type != ORIFICE)
        return error_setInpError(ERR_NAME, tok[2])
      end
    when 6
      if ($Link[link].type != WEIR)
        return error_setInpError(ERR_NAME, tok[2])
      end
    when 7
      if ($Link[link].type != OUTLET)
        return error_setInpError(ERR_NAME, tok[2])
      end
    end
    attrib.v = findmatch(tok[3], $AttribWords)
    if (attrib.v < 0)
      return error_setInpError(ERR_KEYWORD, tok[3])
    end
    if (obj == K_r_CONDUIT)
      if (attrib.v == K_r_STATUS)
        values[0] = (findmatch(tok[5], $ConduitWords)).to_f
        if (values[0] < 0.0)
          return error_setInpError(ERR_KEYWORD, tok[5])
        end
      else
        return error_setInpError(ERR_KEYWORD, tok[3])
      end
    elsif (obj == K_r_PUMP)
      if (attrib.v == K_r_STATUS)
        values[0] = (findmatch(tok[5], $StatusWords)).to_f
        if (values[0] < 0.0)
          return error_setInpError(ERR_KEYWORD, tok[5])
        end
      elsif (attrib.v == K_r_SETTING)
        err = setActionSetting(tok, nToks, curve, tseries, attrib, values)
        if (err > 0)
          return err
        end
      else
        return error_setInpError(ERR_KEYWORD, tok[3])
      end
    elsif (((obj == K_r_ORIFICE) || (obj == K_r_WEIR)) || (obj == K_r_OUTLET))
      if (attrib.v == K_r_SETTING)
        err = setActionSetting(tok, nToks, curve, tseries, attrib, values)
        if (err > 0)
          return err
        end
        if ((attrib.v == K_r_SETTING) && (((values[0] < 0.0) || (values[0] > 1.0))))
          return error_setInpError(ERR_NUMBER, tok[5])
        end
      else
        return error_setInpError(ERR_KEYWORD, tok[3])
      end
    else
      return error_setInpError(ERR_KEYWORD, tok[1])
    end
    n = 6
    if ((curve.v >= 0) || (tseries.v >= 0))
      n = 7
    end
    if (attrib.v == K_r_PID)
      n = 9
    end
    if ((n < nToks) && (findmatch(tok[n], $RuleKeyWords) >= 0))
      return ERR_RULE
    end
    a = TAction.new
    if !(!a.nil?)
      return ERR_MEMORY
    end
    a.rule = r
    a.link = link
    a.attribute = attrib.v
    a.curve = curve.v
    a.tseries = tseries.v
    a.value = values[0]
    if (attrib.v == K_r_PID)
      a.kp = values[0]
      a.ki = values[1]
      a.kd = values[2]
      a.e1 = 0.0
      a.e2 = 0.0
    end
    if ($InputState == K_r_THEN)
      a.next_ = $Rules[r].thenActions
      $Rules[r].thenActions = a
    else
      a.next_ = $Rules[r].elseActions
      $Rules[r].elseActions = a
    end
    return 0
  end

  # controls.c:1028
  def setActionSetting(tok, nToks, curve, tseries, attrib, values)
    k = 0
    m = 0
    if (nToks < 6)
      return error_setInpError(ERR_ITEMS, L0)
    end
    k = findmatch(tok[5], $SettingTypeWords)
    if ((k >= 0) && (nToks < 7))
      return error_setInpError(ERR_ITEMS, L0)
    end
    case k
    when 0
      m = project_findObject(CURVE, tok[6])
      if (m < 0)
        return error_setInpError(ERR_NAME, tok[6])
      end
      curve.v = m
    when 1
      m = project_findObject(TSERIES, tok[6])
      if (m < 0)
        return error_setInpError(ERR_NAME, tok[6])
      end
      tseries.v = m
      $Tseries[m].refersTo = CONTROL
    when 2
      if (nToks < 9)
        return error_setInpError(ERR_ITEMS, L0)
      end
      m = 6
      while (m <= 8)
        if !(getDouble(tok[m], ElemRef.new(values, (m - 6))) != 0)
          return error_setInpError(ERR_NUMBER, tok[m])
        end
        m += 1
      end
      attrib.v = K_r_PID
    else
      if !(getDouble(tok[5], ElemRef.new(values, 0)) != 0)
        return error_setInpError(ERR_NUMBER, tok[5])
      end
    end
    return 0
  end

  # controls.c:1086
  def updateActionValue(a, currentTime, dt)
    if (a.curve >= 0)
      a.value = table_lookup($Curve[a.curve], $ControlValue)
    elsif (a.tseries >= 0)
      a.value = table_tseriesLookup($Tseries[a.tseries], currentTime, 1)
    elsif (a.attribute == K_r_PID)
      a.value = getPIDSetting(a, dt)
    end
  end

  # controls.c:1111
  def getPIDSetting(a, dt)
    e0 = 0.0
    setting = 0.0
    p = 0.0
    i = 0.0
    d = 0.0
    update = 0.0
    tolerance = 0.0001
    dt *= 1440.0
    e0 = ($SetPoint - $ControlValue)
    if (e0.abs > 1e-06)
      if ($SetPoint != 0.0)
        e0 = ($SetPoint == 0.0 ? fdiv0(e0, $SetPoint) : e0 / $SetPoint)
      else
        e0 = ($ControlValue == 0.0 ? fdiv0(e0, $ControlValue) : e0 / $ControlValue)
      end
    end
    if ((e0 - a.e1).abs < tolerance)
      a.e2 = 0.0
      a.e1 = 0.0
    end
    p = ((e0 - a.e1))
    if (a.ki == 0.0)
      i = 0.0
    else
      i = (a.ki == 0.0 ? fdiv0((e0 * dt), a.ki) : (e0 * dt) / a.ki)
    end
    d = (dt == 0.0 ? fdiv0((a.kd * (((e0 - (2.0 * a.e1)) + a.e2))), dt) : (a.kd * (((e0 - (2.0 * a.e1)) + a.e2))) / dt)
    update = (a.kp * (((p + i) + d)))
    if (update.abs < tolerance)
      update = 0.0
    end
    setting = ($Link[a.link].targetSetting + update)
    a.e2 = a.e1
    a.e1 = e0
    if (setting < 0.0)
      setting = 0.0
    end
    if (($Link[a.link].type != PUMP) && (setting > 1.0))
      setting = 1.0
    end
    return setting
  end

  # controls.c:1168
  def updateActionList(a)
    listItem = nil
    a1 = nil
    priority = $Rules[a.rule].priority
    listItem = $ActionList
    while !listItem.nil?
      a1 = listItem.action
      if !(!a1.nil?)
        break
      end
      if (a1.link == a.link)
        if (priority > $Rules[a1.rule].priority)
          listItem.action = a
        end
        return
      end
      listItem = listItem.next_
    end
    if !(!listItem.nil?)
      listItem = TActionList.new
      listItem.next_ = $ActionList
      $ActionList = listItem
    end
    listItem.action = a
  end

  # controls.c:1206
  def executeActionList(currentTime)
    listItem = nil
    nextItem = nil
    a1 = nil
    count = 0
    listItem = $ActionList
    while !listItem.nil?
      a1 = listItem.action
      if !(!a1.nil?)
        break
      end
      if (a1.link >= 0)
        if ($Link[a1.link].targetSetting != a1.value)
          $Link[a1.link].targetSetting = a1.value
          if (((($RptFlags.controls != 0) && (a1.curve < 0)) && (a1.tseries < 0)) && (a1.attribute != K_r_PID))
            report_writeControlAction(currentTime, $Link[a1.link].ID, a1.value, $Rules[a1.rule].ID)
          end
          count += 1
        end
      end
      nextItem = listItem.next_
      listItem = nextItem
    end
    return count
  end

  # controls.c:1243
  def evaluatePremise(p, tStep)
    lhsValue = 0.0
    rhsValue = 0.0
    result = 0
    if (p.exprIndex >= 0)
      lhsValue = mathexpr_eval($Expression[p.exprIndex].expression, method(:getNamedVariableValue))
    else
      lhsValue = getVariableValue(p.lhsVar)
    end
    if (p.value == -10000000000.0)
      rhsValue = getVariableValue(p.rhsVar)
    else
      rhsValue = p.value
    end
    if ((lhsValue == -10000000000.0) || (rhsValue == -10000000000.0))
      return 0
    end
    case p.lhsVar.attribute
    when 15, 17
      return compareTimes(lhsValue, p.relation, rhsValue, (tStep / 2.0))
    when 13, 14
      result = compareTimes(lhsValue, p.relation, rhsValue, (tStep / 2.0))
      $ControlValue = (lhsValue * 24.0)
      return result
    else
      return compareValues(lhsValue, p.relation, rhsValue)
    end
  end

  # controls.c:1286
  def getVariableValue(v)
    i = -1
    j = -1
    if (v.object == K_r_GAGE)
      return getRainValue(v)
    end
    if (v.object == K_r_NODE)
      i = v.index
    end
    if (v.object == K_r_LINK)
      j = v.index
    end
    __ft1 = false
    while true
      if __ft1 || v.attribute == 15
        return $ElapsedTime
      end
      if __ft1 || v.attribute == 16
        return $CurrentDate
      end
      if __ft1 || v.attribute == 17
        return $CurrentTime
      end
      if __ft1 || v.attribute == 19
        return (datetime_dayOfWeek($CurrentDate)).to_f
      end
      if __ft1 || v.attribute == 20
        return (datetime_monthOfYear($CurrentDate)).to_f
      end
      if __ft1 || v.attribute == 18
        return (datetime_dayOfYear($CurrentDate)).to_f
      end
      if __ft1 || v.attribute == 8
        if ((j < 0) || ((($Link[j].type != CONDUIT) && ($Link[j].type != PUMP))))
          return -10000000000.0
        else
          return $Link[j].setting
        end
