  # dynwave.c:224
  def dynwave_execute(tStep)
    converged = 0
    if ($ErrorCode != 0)
      return 0
    end
    $Steps = 0
    converged = 0
    $Omega = $dynwave_OMEGA
    initRoutingStep()
    while ($Steps < $MaxTrials)
      initNodeStates()
      findLinkFlows(tStep)
      converged = findNodeDepths(tStep)
      $Steps += 1
      if ($Steps > 1)
        if (converged != 0)
          break
        end
        findBypassedLinks()
      end
    end
    if !(converged != 0)
      updateConvergenceStats()
    end
    findLimitedLinks()
    return $Steps
  end

