    if ($Node[j].type == STORAGE)
      return node_getMaxOutflow(j, q, dt)
    end
    __sw1 = $Pump[k].type
    case __sw1
    when 0
      return node_getMaxOutflow(j, q, dt)
    when 1, 3, 2
      newNetInflow = (($Node[j].inflow - $Node[j].outflow) - q)
      netFlowVolume = ((0.5 * (($Node[j].oldNetInflow + newNetInflow))) * dt)
      y = ($Node[j].oldDepth + ($Xnode[j].newSurfArea == 0.0 ? fdiv0(netFlowVolume, $Xnode[j].newSurfArea) : netFlowVolume / $Xnode[j].newSurfArea))
