  def updateNodeFlows(i)
    k = 0
    barrels = 1
    n1 = $Link[i].node1
    n2 = $Link[i].node2
    q = $Link[i].newFlow
    conduitLossRate = 0.0
    if (q >= 0.0)
      $Node[n1].outflow += q
      $Node[n2].inflow += q
    else
      $Node[n1].inflow -= q
      $Node[n2].outflow -= q
    end
    if ($Link[i].type == CONDUIT)
      k = $Link[i].subIndex
      barrels = $Conduit[k].barrels
      conduitLossRate = ((($Conduit[k].evapLossRate + $Conduit[k].seepLossRate)) * barrels.to_f)
      if (conduitLossRate > 0.0)
