    end
    $Xnode[$Link[i].node1].newSurfArea += ($Link[i].surfArea1 * barrels.to_f)
    $Xnode[$Link[i].node2].newSurfArea += ($Link[i].surfArea2 * barrels.to_f)
    $Xnode[$Link[i].node1].sumdqdh += $Link[i].dqdh
    if ($Link[i].type == PUMP)
      k = $Link[i].subIndex
      if ($Pump[k].type != TYPE4_PUMP)
        $Xnode[n2].sumdqdh += $Link[i].dqdh
