      link_setOutfallDepth(i)
      i += 1
    end
    i = 0
    while (i < $Nobjects[NODE])
      if ($Node[i].type == OUTFALL)
        i += 1
        next
      end
      yOld = $Node[i].newDepth
      setNodeDepth(i, dt)
      $Xnode[i].converged = 1
      if ((yOld - $Node[i].newDepth).abs > $HeadTol.v)
        $Xnode[i].converged = 0
      end
      i += 1
    end
    i = 0
    while (i < $Nobjects[NODE])
      if ($Node[i].type == OUTFALL)
        i += 1
        next
      end
      if ($Xnode[i].converged == 0)
        return 0
      end
      i += 1
    end
    return 1
  end

