  def getVariableStep(maxStep)
    minLink = BX_getVariableStep_minLink
    minLink.v = -1
    minNode = BX_getVariableStep_minNode
    minNode.v = -1
    tMin = 0.0
    tMinLink = 0.0
    tMinNode = 0.0
    tMin = maxStep
    tMinLink = getLinkStep(tMin, minLink)
    tMinNode = getNodeStep(tMinLink, minNode)
    tMin = tMinLink
    if (tMinNode < tMin)
      tMin = tMinNode
      minLink.v = -1
    end
