    i = 0
    while (i < $Nobjects[TSERIES])
      $Tseries[i].lastDate = ($StartDate.v + $StartTime.v)
      i += 1
    end
    sect = 0
    errsum = 0
    c_rewind($Finp.file)
    while (c_fgets(line, 1024, $Finp.file) != (nil))
      lineCount += 1
      sstrncpy(wLine, line, (1024 & 0xFFFFFFFFFFFFFFFF))
      $Ntokens = getTokens(wLine)
      if ($Ntokens == 0)
        next
      end
      if ($Tok[0][0] == 59)
        next
      end
      lineLength = i32(c_strlen(line))
      if (lineLength >= 1024)
        comment = c_strchr(line, 59)
        if !comment.nil?
          lineLength = i32((cptr_diff(comment, line)))
        end
        if (lineLength >= 1024)
          inperr = ERR_LINE_LENGTH
          report_writeInputErrorMsg(inperr, sect, line, lineCount)
          errsum += 1
        end
      end
      if ($Tok[0][0] == 91)
        newsect = findmatch($Tok[0], $SectWords)
        if (newsect >= 0)
          if (sect == K_s_TRANSECT)
            transect_validate(($Nobjects[TRANSECT] - 1))
          end
          sect = newsect
          next
        else
          inperr = error_setInpError(ERR_KEYWORD, $Tok[0])
          report_writeInputErrorMsg(inperr, sect, line, lineCount)
          errsum += 1
          break
        end
      else
        inperr = parseLine(sect, line)
        if (inperr > 0)
          errsum += 1
          if (errsum > $MAXERRS)
            report_writeLine(L201)
          else
            report_writeInputErrorMsg(inperr, sect, line, lineCount)
          end
        end
      end
      if (errsum > $MAXERRS)
        break
      end
    end
    if (errsum > 0)
      $ErrorCode = ERR_INPUT
    end
    return $ErrorCode
  end

