    while (i < 3)
      if (c_strlen($Title[i]) == (0 & 0xFFFFFFFFFFFFFFFF))
        n = i32(c_strlen(line))
        if (line[(n - 1)] == 10)
          line[(n - 1)] = 32
        end
        sstrncpy($Title[i], line, (1024 & 0xFFFFFFFFFFFFFFFF))
        break
      end
      i += 1
    end
