  # input.c:755
  def readEvent(tok, ntoks)
    x = ::Array.new(4, 0.0)
    if (ntoks < 4)
      return error_setInpError(ERR_ITEMS, L0)
    end
    if !(datetime_strToDate(tok[0], ElemRef.new(x, 0)) != 0)
      return error_setInpError(ERR_DATETIME, tok[0])
    end
    if !(datetime_strToTime(tok[1], ElemRef.new(x, 1)) != 0)
      return error_setInpError(ERR_DATETIME, tok[1])
    end
    if !(datetime_strToDate(tok[2], ElemRef.new(x, 2)) != 0)
      return error_setInpError(ERR_DATETIME, tok[2])
    end
    if !(datetime_strToTime(tok[3], ElemRef.new(x, 3)) != 0)
      return error_setInpError(ERR_DATETIME, tok[3])
    end
    $Event[$Mevents].start = (x[0] + x[1])
    $Event[$Mevents].end_ = (x[2] + x[3])
    if ($Event[$Mevents].start >= $Event[$Mevents].end_)
      return error_setInpError(ERR_DATETIME, L204)
    end
    $Mevents += 1
    return 0
  end

  # input.c:779
  def findmatch(s, keyword)
    i = 0
    while (keyword[i] != (nil))
      if (match(s, keyword[i]) != 0)
        return (i)
      end
      i += 1
    end
    return (-1)
  end

  # input.c:798
  def match(str, substr)
    i = 0
    j = 0
    k = 0
    if !(substr[0] != 0)
      return (0)
    end
    k = 0
    while (str[k] != 0)
      if (str[k] != 32)
        break
      end
      k += 1
    end
    i = k; j = 0
    while (substr[j] != 0)
      if ((!(str[i] != 0)) || (((((((str[i]) >= 97) && ((str[i]) <= 122))) ? (((str[i]) & ~32)) : (str[i]))) != ((((((substr[j]) >= 97) && ((substr[j]) <= 122))) ? (((substr[j]) & ~32)) : (substr[j])))))
        return (0)
      end
      i += 1
      j += 1
    end
    return (1)
  end

  # input.c:828
  def getInt(s, y)
    x = BX_getInt_x
    x.v = 0.0
    if (getDouble(s, x) != 0)
      if (x.v < 0.0)
        x.v -= 0.01
      else
        x.v += 0.01
      end
      y.v = d2i(x.v)
      return 1
    end
    y.v = 0
    return 0
  end

