  # input.c:882
  def getTokens(s)
    len = 0
    n = 0
    m = 0
    c = nil
    n = 0
    while (n < 40)
      $Tok[n] = (nil)
      n += 1
    end
    n = 0
    c = c_strchr(s, 59)
    if !c.nil?
      c[0] = 0
    end
    len = i32(c_strlen(s))
    while ((len > 0) && (n < 40))
      m = i32(c_strcspn(s, L184))
      if (m == 0)
        s = s + 1
      else
        if (s[0] == 34)
          s = s + 1
          len -= 1
          m = i32(c_strcspn(s, L205))
        end
        s[m] = 0
        $Tok[n] = s
        n += 1
        s += (m + 1)
      end
      len -= (m + 1)
    end
    return n
  end

