  def kinwave_execute(j, qinflow, qoutflow, tStep)
    k = 0
    result = 1
    dxdt = 0.0
    dq = 0.0
    ain = 0.0
    aout = BX_kinwave_execute_aout
    aout.v = 0.0
    qin = 0.0
    qout = 0.0
    a1 = 0.0
    a2 = 0.0
    q1 = 0.0
    q2 = 0.0
    q3 = 0.0
    qoutflow.v = (qinflow.v)
    if ($Link[j].type != CONDUIT)
      return result
    end
    if ($Link[j].xsect.type == DUMMY)
      return result
    end
    $pXsect = $Link[j].xsect
    $Qfull = $Link[j].qFull
    $Afull = $Link[j].xsect.aFull
    k = $Link[j].subIndex
    $Beta1 = ($Qfull == 0.0 ? fdiv0($Conduit[k].beta, $Qfull) : $Conduit[k].beta / $Qfull)
    q1 = ($Qfull == 0.0 ? fdiv0($Conduit[k].q1, $Qfull) : $Conduit[k].q1 / $Qfull)
    q2 = ($Qfull == 0.0 ? fdiv0($Conduit[k].q2, $Qfull) : $Conduit[k].q2 / $Qfull)
    qin = ($Qfull == 0.0 ? fdiv0(($Conduit[k].barrels.to_f == 0.0 ? fdiv0((qinflow.v), $Conduit[k].barrels.to_f) : (qinflow.v) / $Conduit[k].barrels.to_f), $Qfull) : ($Conduit[k].barrels.to_f == 0.0 ? fdiv0((qinflow.v), $Conduit[k].barrels.to_f) : (qinflow.v) / $Conduit[k].barrels.to_f) / $Qfull)
    q3 = ($Qfull == 0.0 ? fdiv0(link_getLossRate(j, KW, (qin * $Qfull), tStep), $Qfull) : (link_getLossRate(j, KW, (qin * $Qfull), tStep)) / $Qfull)
    a1 = ($Afull == 0.0 ? fdiv0($Conduit[k].a1, $Afull) : $Conduit[k].a1 / $Afull)
    a2 = ($Afull == 0.0 ? fdiv0($Conduit[k].a2, $Afull) : $Conduit[k].a2 / $Afull)
    if (qin >= 1.0)
      ain = 1.0
    else
      ain = ($Afull == 0.0 ? fdiv0(xsect_getAofS($pXsect, ($Beta1 == 0.0 ? fdiv0(qin, $Beta1) : qin / $Beta1)), $Afull) : (xsect_getAofS($pXsect, ($Beta1 == 0.0 ? fdiv0(qin, $Beta1) : qin / $Beta1))) / $Afull)
    end
    if ((qin <= 1e-06) && (q2 <= 1e-06))
      qout = 0.0
      aout.v = 0.0
    else
      dxdt = ($Qfull == 0.0 ? fdiv0(((tStep == 0.0 ? fdiv0(link_getLength(j), tStep) : (link_getLength(j)) / tStep) * $Afull), $Qfull) : ((tStep == 0.0 ? fdiv0(link_getLength(j), tStep) : (link_getLength(j)) / tStep) * $Afull) / $Qfull)
      dq = (q2 - q1)
      $C1 = ((dxdt * $WT) / $WX)
      $C2 = (((1.0 - $WT)) * ((ain - a1)))
      $C2 = ($C2 - ($WT * a2))
      $C2 = (($C2 * dxdt) / $WX)
      $C2 = (($C2 + ((((1.0 - $WX)) / $WX) * dq)) - qin)
      $C2 = ($C2 + (q3 / $WX))
      aout.v = a2
      result = solveContinuity(qin, ain, aout)
      if (result == -1)
        report_writeErrorMsg(ERR_KINWAVE, $Link[j].ID)
        return 1
      end
      if (result <= 0)
        result = 1
      end
      qout = ($Beta1 * xsect_getSofA($pXsect, (aout.v * $Afull)))
      if (qin > 1.0)
        qin = 1.0
      end
    end
    $Conduit[k].q1 = (qin * $Qfull)
    $Conduit[k].a1 = (ain * $Afull)
    $Conduit[k].q2 = (qout * $Qfull)
    $Conduit[k].a2 = (aout.v * $Afull)
    $Conduit[k].fullState = link_getFullState($Conduit[k].a1, $Conduit[k].a2, $Afull)
    qinflow.v = ($Conduit[k].q1 * $Conduit[k].barrels.to_f)
    qoutflow.v = ($Conduit[k].q2 * $Conduit[k].barrels.to_f)
    return result
  end

  # kinwave.c:170
  def solveContinuity(qin, ain, aout)
    n = 0
    aLo = 0.0
    aHi = 0.0
    aTmp = 0.0
    fLo = 0.0
    fHi = 0.0
    tol = $EPSIL
    aHi = 1.0
    fHi = ((1.0 + $C1) + $C2)
    aLo = ($Afull == 0.0 ? fdiv0(xsect_getAmax($pXsect), $Afull) : (xsect_getAmax($pXsect)) / $Afull)
    if (aLo < aHi)
      fLo = (((($Beta1 * $pXsect.sMax)) + (($C1 * aLo))) + $C2)
    else
      fLo = fHi
    end
    if ((fHi * fLo) > 0.0)
      aHi = aLo
      fHi = fLo
      aLo = 0.0
      fLo = $C2
    end
    if ((fHi * fLo) <= 0.0)
      if ((aout.v < aLo) || (aout.v > aHi))
        aout.v = (0.5 * ((aLo + aHi)))
      end
      if (fLo > fHi)
        aTmp = aLo
        aLo = aHi
        aHi = aTmp
      end
      n = findroot_Newton(aLo, aHi, aout, tol, method(:evalContinuity), (nil))
      if (n <= 0)
        n = -1
      end
    elsif (fLo < 0.0)
      if (qin > 1.0)
        aout.v = ain
      else
        aout.v = 1.0
      end
      n = -2
    elsif (fLo > 0.0)
      aout.v = 0.0
      n = -3
    else
      n = -1
    end
    return n
  end

  # kinwave.c:261
  def evalContinuity(a, f, df, p)
    f.v = (((($Beta1 * xsect_getSofA($pXsect, (a * $Afull)))) + (($C1 * a))) + $C2)
    df.v = (((($Beta1 * $Afull) * xsect_getdSdA($pXsect, (a * $Afull)))) + $C1)
  end

  # landuse.c:51
  def landuse_readParams(j, tok, ntoks)
    id = nil
    if (ntoks < 1)
      return error_setInpError(ERR_ITEMS, L0)
    end
    id = project_findID(LANDUSE, tok[0])
    if (id == (nil))
      return error_setInpError(ERR_NAME, tok[0])
    end
    $Landuse[j].ID = id
    if (ntoks > 1)
      if (ntoks < 4)
        return error_setInpError(ERR_ITEMS, L0)
      end
      if !(getDouble(tok[1], fieldref($Landuse[j], :sweepInterval)) != 0)
        return error_setInpError(ERR_NUMBER, tok[1])
      end
      if !(getDouble(tok[2], fieldref($Landuse[j], :sweepRemoval)) != 0)
        return error_setInpError(ERR_NUMBER, tok[2])
      end
      if !(getDouble(tok[3], fieldref($Landuse[j], :sweepDays0)) != 0)
        return error_setInpError(ERR_NUMBER, tok[3])
      end
    else
      $Landuse[j].sweepInterval = 0.0
      $Landuse[j].sweepRemoval = 0.0
      $Landuse[j].sweepDays0 = 0.0
    end
    if (($Landuse[j].sweepRemoval < 0.0) || ($Landuse[j].sweepRemoval > 1.0))
      return error_setInpError(ERR_NUMBER, tok[2])
    end
    return 0
  end

