  def landuse_readBuildupParams(tok, ntoks)
    i = 0
    j = 0
    k = 0
    n = 0
    p = 0
    c = [0.0, 0.0, 0.0]
    tmax = 0.0
    if (ntoks < 3)
      return 0
    end
    j = project_findObject(LANDUSE, tok[0])
    if (j < 0)
      return error_setInpError(ERR_NAME, tok[0])
    end
    p = project_findObject(POLLUT, tok[1])
    if (p < 0)
      return error_setInpError(ERR_NAME, tok[1])
    end
    k = findmatch(tok[2], $BuildupTypeWords)
    if (k < 0)
      return error_setInpError(ERR_KEYWORD, tok[2])
    end
    $Landuse[j].buildupFunc[p].funcType = k
    if (k > NO_BUILDUP)
      if (ntoks < 7)
        return error_setInpError(ERR_ITEMS, L0)
      end
      if (k != EXTERNAL_BUILDUP)
        i = 0
        while (i < 3)
          if ((!(getDouble(tok[(i + 3)], ElemRef.new(c, i)) != 0)) || (c[i] < 0.0))
            return error_setInpError(ERR_NUMBER, tok[(i + 3)])
          end
          i += 1
        end
      end
      n = findmatch(tok[6], $NormalizerWords)
      if (n < 0)
        return error_setInpError(ERR_KEYWORD, tok[6])
      end
      $Landuse[j].buildupFunc[p].normalizer = n
    end
    __sw1 = $Landuse[j].buildupFunc[p].funcType
    case __sw1
    when 1
      if ((c[2] > 0.0) && (((c[2] < 0.01) || (c[2] > 10.0))))
        return error_setInpError(ERR_KEYWORD, tok[5])
      end
      if ((c[1] * c[2]) == 0.0)
        tmax = 0.0
      elsif ((c[2] == 0.0 ? fdiv0(c_log10(c[0]), c[2]) : (c_log10(c[0])) / c[2]) > 3.5)
        tmax = 3650.0
      else
        tmax = ((__p2 = (c[1] == 0.0 ? fdiv0(c[0], c[1]) : c[0] / c[1])) < 0.0 ? c_powneg(__p2, (c[2] == 0.0 ? fdiv0(1.0, c[2]) : 1.0 / c[2])) : __p2 ** (c[2] == 0.0 ? fdiv0(1.0, c[2]) : 1.0 / c[2]))
      end
    when 2
      if (c[1] == 0.0)
        tmax = 0.0
      else
        tmax = (c[1] == 0.0 ? fdiv0(-(c_log(0.001)), c[1]) : (-(c_log(0.001))) / c[1])
      end
    when 3
      tmax = (1000.0 * c[2])
    when 4
      if ((!(getDouble(tok[3], ElemRef.new(c, 0)) != 0)) || (c[0] < 0.0))
        return error_setInpError(ERR_NUMBER, tok[3])
      end
      if ((!(getDouble(tok[4], ElemRef.new(c, 1)) != 0)) || (c[1] < 0.0))
        return error_setInpError(ERR_NUMBER, tok[3])
      end
      n = project_findObject(TSERIES, tok[5])
      if (n < 0)
        return error_setInpError(ERR_NAME, tok[4])
      end
      $Tseries[n].refersTo = EXTERNAL_BUILDUP
      c[2] = n.to_f
      tmax = 0.0
    else
      tmax = 0.0
    end
    $Landuse[j].buildupFunc[p].coeff[0] = c[0]
    $Landuse[j].buildupFunc[p].coeff[1] = c[1]
    $Landuse[j].buildupFunc[p].coeff[2] = c[2]
    $Landuse[j].buildupFunc[p].maxDays = tmax
    return 0
  end

  # landuse.c:281
  def landuse_readWashoffParams(tok, ntoks)
    i = 0
    j = 0
    p = 0
    func = 0
    x = ::Array.new(4, 0.0)
    if (ntoks < 3)
      return 0
    end
    i = 0
    while (i < 4)
      x[i] = 0.0
      i += 1
    end
    func = NO_WASHOFF
    j = project_findObject(LANDUSE, tok[0])
    if (j < 0)
      return error_setInpError(ERR_NAME, tok[0])
    end
    p = project_findObject(POLLUT, tok[1])
    if (p < 0)
      return error_setInpError(ERR_NAME, tok[1])
    end
    if (ntoks > 2)
      func = findmatch(tok[2], $WashoffTypeWords)
      if (func < 0)
        return error_setInpError(ERR_KEYWORD, tok[2])
      end
      if (func != NO_WASHOFF)
        if (ntoks < 5)
          return error_setInpError(ERR_ITEMS, L0)
        end
        if !(getDouble(tok[3], ElemRef.new(x, 0)) != 0)
          return error_setInpError(ERR_NUMBER, tok[3])
        end
        if !(getDouble(tok[4], ElemRef.new(x, 1)) != 0)
          return error_setInpError(ERR_NUMBER, tok[4])
        end
        if (ntoks >= 6)
          if !(getDouble(tok[5], ElemRef.new(x, 2)) != 0)
            return error_setInpError(ERR_NUMBER, tok[5])
          end
        end
        if (ntoks >= 7)
          if !(getDouble(tok[6], ElemRef.new(x, 3)) != 0)
            return error_setInpError(ERR_NUMBER, tok[6])
          end
        end
      end
    end
    if (x[0] < 0.0)
      return error_setInpError(ERR_NUMBER, tok[3])
    end
    if ((x[1] < -10.0) || (x[1] > 10.0))
      return error_setInpError(ERR_NUMBER, tok[4])
    end
    if ((x[2] < 0.0) || (x[2] > 100.0))
      return error_setInpError(ERR_NUMBER, tok[5])
    end
    if ((x[3] < 0.0) || (x[3] > 100.0))
      return error_setInpError(ERR_NUMBER, tok[6])
    end
    if (func == EXPON_WASHOFF)
      x[0] = (x[0] / 3600.0)
    end
    if (func == RATING_WASHOFF)
      x[0] = x[0] * ((__p1 = UCF(FLOW)) < 0.0 ? c_powneg(__p1, x[1]) : __p1 ** x[1])
    end
    if (func == EMC_WASHOFF)
      x[0] *= 28.317
    end
    $Landuse[j].washoffFunc[p].funcType = func
    $Landuse[j].washoffFunc[p].coeff = x[0]
    $Landuse[j].washoffFunc[p].expon = x[1]
    $Landuse[j].washoffFunc[p].sweepEffic = (x[2] / 100.0)
    $Landuse[j].washoffFunc[p].bmpEffic = (x[3] / 100.0)
    return 0
  end

