        lidUnit = lidList.lidUnit
        i = lidUnit.lidIndex
        k = lidUnit.drainSubcatch
        if ((k >= 0) && (k != j))
          q = lidUnit.oldDrainFlow
          subcatch_addRunonFlow(k, q)
          p = 0
          while (p < $Nobjects[POLLUT])
            w = ((q * $Subcatch[j].oldQual[p]) * 28.317)
            w = (w * ((1.0 - $LidProcs[i].drainRmvl[p])))
            $Subcatch[k].newQual[p] += w
            p += 1
          end
        end
        lidList = lidList.nextLidUnit
      end
    end
  end

  # lid.c:1549
  def lid_addDrainInflow(j, f)
    i = 0
    k = 0
    p = 0
    q = 0.0
    w = 0.0
    w1 = 0.0
    w2 = 0.0
    lidUnit = nil
    lidList = nil
    lidGroup = nil
