        x[i] = (((((x[i]) >= (xMin[i]))) ? (x[i]) : (xMin[i])))
        if ((omega > 0.0) && ((x[i] - xPrev[i]).abs > xTol[i]))
          canStop = 0
        end
        xPrev[i] = x[i]
        i += 1
      end
      if (canStop != 0)
        return steps
      end
      steps += 1
    end
    return 0
  end

