        evapLossRate = (totalLossRate == 0.0 ? fdiv0((evapLossRate * q), totalLossRate) : (evapLossRate * q) / totalLossRate)
        seepLossRate = (totalLossRate == 0.0 ? fdiv0((seepLossRate * q), totalLossRate) : (seepLossRate * q) / totalLossRate)
        totalLossRate = q
      end
    end
    $Conduit[$Link[j].subIndex].evapLossRate = evapLossRate
    $Conduit[$Link[j].subIndex].seepLossRate = seepLossRate
