  def project_validate()
    i = 0
    j = 0
    err = 0
    i = 0
    while (i < $Nobjects[CURVE])
      err = table_validate($Curve[i])
      if (err != 0)
        report_writeErrorMsg(ERR_CURVE_SEQUENCE, $Curve[i].ID)
      end
      i += 1
    end
    i = 0
    while (i < $Nobjects[TSERIES])
      err = table_validate($Tseries[i])
      if (err != 0)
        report_writeTseriesErrorMsg(err, $Tseries[i])
      end
      i += 1
    end
    climate_validate()
    lid_validate()
    if ($Nobjects[SNOWMELT] == 0)
      $IgnoreSnowmelt = 1
    end
    if ($Nobjects[AQUIFER] == 0)
      $IgnoreGwater = 1
    end
    i = 0
    while (i < $Nobjects[AQUIFER])
      gwater_validateAquifer(i)
      i += 1
    end
    i = 0
    while (i < $Nobjects[SUBCATCH])
      subcatch_validate(i)
      i += 1
    end
    i = 0
    while (i < $Nobjects[GAGE])
      gage_validate(i)
      i += 1
    end
    i = 0
    while (i < $Nobjects[SNOWMELT])
      snow_validateSnowmelt(i)
      i += 1
    end
    j = 0
    i = 0
    while (i < $Nobjects[CURVE])
      if ($Curve[i].curveType == SHAPE_CURVE)
        $Curve[i].refersTo = j
        $Shape[j].curve = i
        if !(shape_validate($Shape[j], $Curve[i]) != 0)
          report_writeErrorMsg(ERR_CURVE_SEQUENCE, $Curve[i].ID)
        end
        j += 1
      end
      i += 1
    end
    i = 0
    while (i < $Nobjects[NODE])
      $Node[i].oldDepth = $Node[i].fullDepth
      i += 1
    end
    i = 0
    while (i < $Nobjects[LINK])
      link_validate(i)
      i += 1
    end
    i = 0
    while (i < $Nobjects[NODE])
      node_validate(i)
      i += 1
    end
    if ($DryStep < $WetStep)
      report_writeWarningMsg(L319, L0)
      $DryStep = $WetStep
    end
    if ($RouteStep > $WetStep.to_f)
      report_writeWarningMsg(L320, L0)
      $RouteStep = $WetStep.to_f
    end
    if ($RptFlags.subcatchments == ALL)
      i = 0
      while (i < $Nobjects[SUBCATCH])
        $Subcatch[i].rptFlag = 1
        i += 1
      end
    end
    if ($RptFlags.nodes == ALL)
      i = 0
      while (i < $Nobjects[NODE])
        $Node[i].rptFlag = 1
        i += 1
      end
    end
    if ($RptFlags.links == ALL)
      i = 0
      while (i < $Nobjects[LINK])
        $Link[i].rptFlag = 1
        i += 1
      end
    end
    if ($RouteModel == DW)
      dynwave_validate()
    end
    inlet_validate()
    if ($NumThreads == 0)
      $NumThreads = omp_get_max_threads()
    else
      $NumThreads = ((((($NumThreads) <= (omp_get_max_threads()))) ? ($NumThreads) : (omp_get_max_threads())))
    end
    if ($Nobjects[LINK] < (4 * $NumThreads))
      $NumThreads = 1
    end
  end

