    end
    vIn = (qIn * tStep)
    cIn = (vIn == 0.0 ? fdiv0((wIn * tStep), vIn) : (wIn * tStep) / vIn)
    cMax = (((((c) >= (cIn))) ? (c) : (cIn)))
