  def findLinkMassFlow(i, tStep)
    j = 0
    p = 0
    qLink = 0.0
    w = 0.0
    qLink = $Link[i].newFlow
    j = $Link[i].node2
    if (qLink < 0.0)
      j = $Link[i].node1
    end
    qLink = qLink.abs
    if ($RouteModel != DW)
      qLink -= (inlet_capturedFlow(i))
    end
    p = 0
    while (p < $Nobjects[POLLUT])
      w = (qLink * $Link[i].oldQual[p])
      $Node[j].newQual[p] += w
      $Link[i].totalLoad[p] += (w * tStep)
      p += 1
    end
    $Node[j].qualInflow += qLink
  end

  # qualrout.c:221
  def findNodeQual(j)
    p = 0
    qNode = 0.0
    qNode = $Node[j].qualInflow
    if (qNode > 1e-10)
      p = 0
      while (p < $Nobjects[POLLUT])
        $Node[j].newQual[p] = (qNode == 0.0 ? fdiv0($Node[j].newQual[p], qNode) : $Node[j].newQual[p] / qNode)
        p += 1
      end
    else
      p = 0
      while (p < $Nobjects[POLLUT])
        if ($Node[j].newDepth > $ZeroDepth)
          $Node[j].newQual[p] = $Node[j].oldQual[p]
        else
          $Node[j].newQual[p] = 0.0
        end
        p += 1
      end
    end
  end

  # qualrout.c:253
  def findLinkQual(i, tStep)
    j = 0
    k = 0
    p = 0
    wIn = 0.0
    qIn = 0.0
    qSeep = 0.0
    v1 = 0.0
    v2 = 0.0
    c1 = 0.0
    c2 = 0.0
    vEvap = 0.0
    vLosses = 0.0
    fEvap = 0.0
    barrels = 0.0
    j = $Link[i].node1
    if ($Link[i].newFlow < 0.0)
      j = $Link[i].node2
    end
    if (($Link[i].type != CONDUIT) || ($Link[i].xsect.type == DUMMY))
      p = 0
      while (p < $Nobjects[POLLUT])
        $Link[i].newQual[p] = $Node[j].newQual[p]
        p += 1
      end
      return
    end
    k = $Link[i].subIndex
    barrels = $Conduit[k].barrels.to_f
    qIn = ($Conduit[k].q1.abs * barrels)
    qSeep = ($Conduit[k].seepLossRate * barrels)
    vEvap = (($Conduit[k].evapLossRate * barrels) * tStep)
    v1 = $Link[i].oldVolume
    v2 = $Link[i].newVolume
    vLosses = ((qSeep * tStep) + vEvap)
    fEvap = 1.0
    if ((vEvap > 0.0) && (v1 > $ZeroVolume))
      fEvap += (v1 == 0.0 ? fdiv0(vEvap, v1) : vEvap / v1)
    end
    if ($RouteModel == SF)
      findSFLinkQual(i, qSeep, fEvap, tStep)
      return
    end
    if ($RouteModel == DW)
      qIn = (qIn + (tStep == 0.0 ? fdiv0((((v2 + vLosses) - v1)), tStep) : (((v2 + vLosses) - v1)) / tStep))
      qIn = (((((qIn) >= (0.0))) ? (qIn) : (0.0)))
    end
    p = 0
    while (p < $Nobjects[POLLUT])
      c1 = $Link[i].oldQual[p]
      massbal_addSeepageLoss(p, (qSeep * c1))
      c1 *= fEvap
      c2 = getReactedQual(p, c1, v1, tStep)
      wIn = ($Node[j].newQual[p] * qIn)
      c2 = getMixedQual(c2, v1, wIn, qIn, tStep)
      if ((v2 < $ZeroVolume) || ($Link[i].newDepth <= $ZeroDepth))
        massbal_addToFinalStorage(p, (c2 * v2))
        c2 = 0.0
      end
      $Link[i].newQual[p] = c2
      p += 1
    end
  end

  # qualrout.c:357
  def findSFLinkQual(i, qSeep, fEvap, tStep)
    j = $Link[i].node1
    p = 0
    c1 = 0.0
    c2 = 0.0
    lossRate = 0.0
    p = 0
    while (p < $Nobjects[POLLUT])
      c1 = $Node[j].newQual[p]
      massbal_addSeepageLoss(p, (qSeep * c1))
      c1 *= fEvap
      c2 = c1
      if ($Pollut[p].kDecay > 0.0)
        c2 = (c1 * ::Math.exp((-$Pollut[p].kDecay * tStep)))
        c2 = (((((0.0) >= (c2))) ? (0.0) : (c2)))
        lossRate = (((c1 - c2)) * $Link[i].newFlow)
        massbal_addReactedMass(p, lossRate)
      end
      $Link[i].newQual[p] = c2
      p += 1
    end
  end

