      return 0
    end
    date1 = datetime_encodeDate(year.v, month.v, day.v)
    if ((day1 != -693594.0) && (date1 < day1))
      return 0
    end
    if ((day2 != -693594.0) && (date1 > day2))
      return -1
    end
    date2 = (date1 + datetime_encodeTime(hour.v, minute.v, 0))
    if (date2 <= $PreviousDate)
