      if (x.v >= $RainAccum)
        x.v = f32(x.v - $RainAccum)
        $RainAccum = f32($RainAccum + x.v)
      else
        $RainAccum = x.v
      end
    end
    x.v = f32(x.v * (f32($UnitsFactor)))
    saveRainfall(date1, hour.v, minute.v, x.v, 0)
    return 1
  end

