  # rdii.c:720
  def createRdiiFile()
    hasRdii = 0
    elapsedTime = 0.0
    duration = 0.0
    currentDate = 0.0
    $RdiiStep.v = $WetStep
    $NumRdiiNodes.v = getNumRdiiNodes()
    if ($NumRdiiNodes.v == 0)
      $Frdii.mode = NO_FILE
      return
    elsif ($Frdii.mode == NO_FILE)
      $Frdii.mode = SCRATCH_FILE
    end
    validateRdii()
    initGageData()
    if ($ErrorCode != 0)
      return
    end
    openRdiiProcessor()
    if !($ErrorCode != 0)
      initUnitHydData()
      duration = ($TotalDuration / 1000.0)
      elapsedTime = 0.0
      while ((elapsedTime <= duration) && (!($ErrorCode != 0)))
        currentDate = ($StartDateTime + (elapsedTime / 86400.0))
        getRainfall(currentDate)
        getUnitHydRdii(currentDate)
        hasRdii = getNodeRdii()
        if (hasRdii != 0)
          saveRdiiFlows(currentDate)
        end
        elapsedTime += $RdiiStep.v.to_f
      end
    end
    closeRdiiProcessor()
  end

