  # rdii.c:813
  def validateRdii()
    i = 0
    j = 0
    k = 0
    m = 0
    rsum = 0.0
    j = 0
    while (j < $Nobjects[UNITHYD])
      m = 0
      while (m < 12)
        rsum = 0.0
        k = 0
        while (k < 3)
          if ($UnitHyd[j].tBase[m][k] == 0)
            k += 1
            next
          end
          if ($UnitHyd[j].tPeak[m][k].to_f < 0.0)
            report_writeErrorMsg(ERR_UNITHYD_TIMES, $UnitHyd[j].ID)
          end
          if ($UnitHyd[j].r[m][k] < 0.0)
            report_writeErrorMsg(ERR_UNITHYD_RATIOS, $UnitHyd[j].ID)
          else
            rsum += $UnitHyd[j].r[m][k]
          end
          k += 1
        end
        if (rsum > 1.01)
          report_writeErrorMsg(ERR_UNITHYD_RATIOS, $UnitHyd[j].ID)
        end
        m += 1
      end
      j += 1
    end
    i = 0
    while (i < $Nobjects[NODE])
      if !$Node[i].rdiiInflow.nil?
        if ($Node[i].rdiiInflow.area < 0.0)
          report_writeErrorMsg(ERR_RDII_AREA, $Node[i].ID)
        end
      end
      i += 1
    end
  end

