  def report_readOptions(tok, ntoks)
    k = 0
    j = 0
    m = 0
    t = 0
    if (ntoks < 2)
      return error_setInpError(ERR_ITEMS, L0)
    end
    k = findmatch(tok[0], $ReportWords)
    if (k < 0)
      return error_setInpError(ERR_KEYWORD, tok[0])
    end
    if ((k < 2) || (k > 4))
      m = findmatch(tok[1], $NoYesWords)
      if ((m < NO) || (m > YES))
        return error_setInpError(ERR_KEYWORD, tok[1])
      end
      case k
      when 0
        $RptFlags.disabled = m
        return 0
      when 1
        $RptFlags.input = m
        return 0
      when 5
        $RptFlags.continuity = m
        return 0
      when 6
        $RptFlags.flowStats = m
        return 0
      when 7
        $RptFlags.controls = m
        return 0
      when 8
        $RptFlags.averages = m
        return 0
      when 9
        return 0
      else
        return error_setInpError(ERR_KEYWORD, tok[1])
      end
    else
      case k
      when 2
        m = SUBCATCH
      when 3
        m = NODE
      when 4
        m = LINK
      end
    end
    if (strcomp(tok[1], L355) != 0)
      k = NONE
    elsif (strcomp(tok[1], L351) != 0)
      k = ALL
    else
      k = SOME
      t = 1
      while (t < ntoks)
        j = project_findObject(m, tok[t])
        if (j < 0)
          return error_setInpError(ERR_NAME, tok[t])
        end
        case m
        when 1
          $Subcatch[j].rptFlag = 1
        when 2
          $Node[j].rptFlag = 1
        when 3
          $Link[j].rptFlag = 1
        end
        t += 1
      end
    end
    case m
    when 1
      $RptFlags.subcatchments = k
    when 2
      $RptFlags.nodes = k
    when 3
      $RptFlags.links = k
    end
    return 0
  end

