  # report.c:923
  def report_writeMaxStats(maxMassBalErrs, maxCourantCrit, nMaxStats)
    i = 0
    j = 0
    k = 0
    if (($RouteModel != DW) || ($Nobjects[LINK] == 0))
      return
    end
    if (nMaxStats <= 0)
      return
    end
    if (maxMassBalErrs[0].index >= 0)
      report_writeLine((L0))
      report_writeLine((L470))
      report_writeLine((L471))
      report_writeLine((L470))
      i = 0
      while (i < nMaxStats)
        j = maxMassBalErrs[i].index
        if (j < 0)
          i += 1
          next
        end
        c_fprintf($Frpt.file, L472, $Node[j].ID, maxMassBalErrs[i].value)
        i += 1
      end
      report_writeLine((L0))
    end
    if ($CourantFactor.v == 0.0)
      return
    end
    report_writeLine((L0))
    report_writeLine((L473))
    report_writeLine((L474))
    report_writeLine((L473))
    k = 0
    i = 0
    while (i < nMaxStats)
      j = maxCourantCrit[i].index
      if (j < 0)
        i += 1
        next
      end
      k += 1
      if (maxCourantCrit[i].objType == NODE)
        c_fprintf($Frpt.file, L475, $Node[j].ID)
      else
        c_fprintf($Frpt.file, L476, $Link[j].ID)
      end
      c_fprintf($Frpt.file, L477, maxCourantCrit[i].value)
      i += 1
    end
    if (k == 0)
      c_fprintf($Frpt.file, L478)
    end
    report_writeLine((L0))
  end

