  # report.c:1037
  def report_writeTimeStepStats(timeStepStats)
    timeStepCount = timeStepStats.timeStepCount.to_f
    totalRoutingTime = 0.0
    fSteadyState = 0.0
    if (($Nobjects[LINK] == 0) || (timeStepStats.timeStepCount.to_f == 0.0))
      return
    end
    totalRoutingTime = (timeStepStats.steadyStateTime + timeStepStats.routingTime)
    if (totalRoutingTime > 0.0)
      fSteadyState = (totalRoutingTime == 0.0 ? fdiv0((100.0 * timeStepStats.steadyStateTime), totalRoutingTime) : (100.0 * timeStepStats.steadyStateTime) / totalRoutingTime)
    end
    report_writeLine((L0))
    report_writeLine((L470))
    report_writeLine((L486))
    report_writeLine((L470))
    c_fprintf($Frpt.file, L487, timeStepStats.minTimeStep)
    c_fprintf($Frpt.file, L488, (timeStepCount == 0.0 ? fdiv0(timeStepStats.routingTime, timeStepCount) : timeStepStats.routingTime / timeStepCount))
    c_fprintf($Frpt.file, L489, timeStepStats.maxTimeStep)
    c_fprintf($Frpt.file, L490, (((((fSteadyState) <= (100.0))) ? (fSteadyState) : (100.0))))
    c_fprintf($Frpt.file, L491, (timeStepCount == 0.0 ? fdiv0(timeStepStats.trialsCount, timeStepCount) : timeStepStats.trialsCount / timeStepCount))
    c_fprintf($Frpt.file, L492, (timeStepCount == 0.0 ? fdiv0((100.0 * $NonConvergeCount.to_f), timeStepCount) : (100.0 * $NonConvergeCount.to_f) / timeStepCount))
    if (($RouteModel == DW) && ($CourantFactor.v > 0.0))
      report_RouteStepFreq(timeStepStats)
    end
    report_writeLine((L0))
  end

  # report.c:1085
  def report_RouteStepFreq(timeStepStats)
    totalSteps = 0.0
    i = 0
    i = 1
    while (i < 6)
      totalSteps += timeStepStats.timeStepCounts[i].to_f
      i += 1
    end
    if (totalSteps == 0.0)
      return
    end
    c_fprintf($Frpt.file, L493)
    i = 1
    while (i < 6)
      c_fprintf($Frpt.file, L494, timeStepStats.timeStepIntervals[(i - 1)], timeStepStats.timeStepIntervals[i], (totalSteps == 0.0 ? fdiv0((100.0 * (timeStepStats.timeStepCounts[i]).to_f), totalSteps) : (100.0 * (timeStepStats.timeStepCounts[i]).to_f) / totalSteps))
      i += 1
    end
  end

  # report.c:1113
  def report_writeReport()
    if ($ErrorCode != 0)
      return
    end
    if ($Nperiods == 0)
      return
    end
    if (($RptFlags.subcatchments != NONE) && (((($IgnoreRainfall == 0) || ($IgnoreSnowmelt == 0)) || ($IgnoreGwater == 0))))
      report_Subcatchments()
    end
    if (($IgnoreRouting == 1) && ($IgnoreQuality == 1))
      return
    end
    if ($RptFlags.nodes != NONE)
      report_Nodes()
    end
    if ($RptFlags.links != NONE)
      report_Links()
    end
  end

  # report.c:1135
  def report_Subcatchments()
    j = 0
    p = 0
    k = 0
    period = 0
    days = BX_report_Subcatchments_days
    days.v = 0.0
    theDate = CPtr.buf(12)
    theTime = CPtr.buf(9)
    hasSnowmelt = (((($Nobjects[SNOWMELT] > 0) && (!($IgnoreSnowmelt != 0)))) ? 1 : 0)
    hasGwater = (((($Nobjects[AQUIFER] > 0) && (!($IgnoreGwater != 0)))) ? 1 : 0)
    hasQuality = (((($Nobjects[POLLUT] > 0) && (!($IgnoreQuality != 0)))) ? 1 : 0)
    if ($Nobjects[SUBCATCH] == 0)
      return
    end
    report_writeLine((L0))
    report_writeLine((L479))
    report_writeLine((L495))
    report_writeLine((L479))
    j = 0
    while (j < $Nobjects[SUBCATCH])
      k = ($Subcatch[j].rptFlag - 1)
