  # roadway.c:85
  def roadway_getInflow(j, dir, hRoad, h1, h2)
    k = 0
    roadSurf = 0
    useVariableCd = 0
    length = 0.0
    roadWidth = 0.0
    hWr = 0.0
    ht = 0.0
    cD = 0.0
    q = 0.0
    dqdh = 0.0
    if ($Link[j].type != WEIR)
      return 0.0
    end
    k = $Link[j].subIndex
    roadWidth = $Weir[k].roadWidth
    roadSurf = $Weir[k].roadSurface
    cD = $Weir[k].cDisch1
    if ($UnitSystem == SI)
      cD = (cD / 0.552)
    end
    useVariableCd = 0
    if ((roadWidth > 0.0) && (roadSurf >= 1))
      useVariableCd = 1
    end
    hWr = (h1 - hRoad)
    ht = (h2 - hRoad)
    if (hWr > 0.0001)
      if (useVariableCd != 0)
        cD = getCd(hWr, ht, roadWidth, roadSurf)
      end
      length = $Link[j].xsect.wMax
      q = ((cD * length) * (hWr < 0.0 ? c_powneg(hWr, 1.5) : hWr ** 1.5))
      dqdh = (hWr == 0.0 ? fdiv0((1.5 * q), hWr) : (1.5 * q) / hWr)
    end
    $Link[j].dqdh = dqdh
    $Link[j].newDepth = ((((((h1 - hRoad)) >= (0.0))) ? ((h1 - hRoad)) : (0.0)))
    $Link[j].flowClass = SUBCRITICAL
    if (hRoad > h2)
      if (dir == 1.0)
        $Link[j].flowClass = DN_CRITICAL
      else
        $Link[j].flowClass = UP_CRITICAL
      end
    end
    return (dir * q)
  end

  # roadway.c:146
  def getCd(hWr, ht, roadWidth, roadSurf)
    kT = 1.0
    hL = 0.0
    htH = 0.0
    cR = 0.0
    if (hWr <= 0.0)
      return 0.0
    end
    hL = (roadWidth == 0.0 ? fdiv0(hWr, roadWidth) : hWr / roadWidth)
    if (hL <= 0.15)
      if (roadSurf == PAVED)
        cR = getY(hWr, $Cr_Low_Paved, $N_Cr_Low_Paved)
      else
        cR = getY(hWr, $Cr_Low_Gravel, $N_Cr_Low_Gravel)
      end
    else
      if (roadSurf == PAVED)
        cR = getY(hL, $Cr_High_Paved, $N_Cr_High_Paved)
      else
        cR = getY(hL, $Cr_High_Gravel, $N_Cr_High_Gravel)
      end
    end
    if (ht > 0.0)
      htH = (hWr == 0.0 ? fdiv0(ht, hWr) : ht / hWr)
      if (roadSurf == PAVED)
        kT = getY(htH, $Kt_Paved, $N_Kt_Paved)
      else
        kT = getY(htH, $Kt_Gravel, $N_Kt_Gravel)
      end
    end
    return (cR * kT)
  end

  # roadway.c:176
  def getY(x, table, n)
    i = 0
    x1 = 0.0
    y1 = 0.0
    dx = 0.0
    dy = 0.0
    if (x <= table[0][0])
      return table[0][1]
    end
    if (x >= (table[(n - 1)])[0])
      return (table[(n - 1)])[1]
    end
    i = 1
    while (i < n)
      if (x <= table[i][0])
        x1 = (table[(i - 1)])[0]
        dx = (table[i][0] - x1)
        y1 = (table[(i - 1)])[1]
        dy = (table[i][1] - y1)
        return (y1 + (dx == 0.0 ? fdiv0((((x - x1)) * dy), dx) : (((x - x1)) * dy) / dx))
      end
      i += 1
    end
    return (table[(n - 1)])[1]
  end

