  def routing_open()
    if !(treatmnt_open() != 0)
      return $ErrorCode
    end
    $SortedLinks = (nil)
    if ($Nobjects[LINK] > 0)
      $SortedLinks = ::Array.new(($Nobjects[LINK] & 0xFFFFFFFFFFFFFFFF), 0)
      if !(!$SortedLinks.nil?)
        report_writeErrorMsg(ERR_MEMORY, L0)
        return $ErrorCode
      end
      toposort_sortLinks($SortedLinks)
      if ($ErrorCode != 0)
        return $ErrorCode
      end
    end
    iface_openRoutingFiles()
    flowrout_init($RouteModel)
    if ($Fhotstart1.mode == NO_FILE)
      qualrout_init()
    end
    if ($NumEvents > 0)
      sortEvents()
    end
    $NextEvent = 0
    $BetweenEvents = ((($NumEvents > 0)) ? 1 : 0)
    $NewRuleTime = 0.0
    return $ErrorCode
  end

