  # routing.c:337
  def isBetweenEvents(currentDate)
    if ($NumEvents == 0)
      return 0
    end
    if (currentDate > $Event[$NextEvent].end_)
      $NextEvent += 1
      return 1
    elsif (currentDate >= $Event[$NextEvent].start)
      return 0
    end
    return 1
  end

