  # routing.c:929
  def sortEvents()
    i = 0
    j = 0
    gap = 0
    temp = TEvent.new
    gap = idiv($NumEvents, 2)
    while (gap >= 1)
      i = gap
      while (i < $NumEvents)
        temp = $Event[i].copy
        j = (i - gap)
        while ((j >= 0) && ($Event[j].start > temp.start))
          $Event[(j + gap)] = $Event[j].copy
          j -= gap
        end
        if (j != (i - gap))
          $Event[(j + gap)] = temp.copy
        end
        i += gap
      end
      gap = idiv(gap, 2)
    end
    i = 0
    while (i < ($NumEvents - 1))
      if ($Event[i].end_ > ($Event[(i + 1)]).start)
        $Event[i].end_ = ($Event[(i + 1)]).start
      end
      i += 1
    end
  end

